const data = $input.first().json;

// Guard: Slack API error
if (data.ok === false) {
  return [{
    json: {
      error: true,
      error_reason: data.error || "Unknown Slack API error",
      formatted_thread: ""
    }
  }];
}

const messages = data.messages ?? [];

// Slack returns newest-first → reverse to chronological order
const ordered = [...messages].reverse();

// Filter out noise: bot messages, join/leave, empty text
const cleaned = ordered.filter(m =>
  m.type === "message" &&
  !m.subtype &&                    // removes channel_join, bot_message, etc.
  m.text &&
  m.text.trim().length > 0
);

// Guard: nothing usable
if (cleaned.length === 0) {
  return [{
    json: {
      error: true,
      error_reason: "No usable messages found in the channel.",
      formatted_thread: ""
    }
  }];
}

// Build a clean conversation transcript
const transcript = cleaned
  .map(m => `<@${m.user}>: ${m.text}`)
  .join("\n");

return [{
  json: {
    error: false,
    message_count: cleaned.length,
    formatted_thread: transcript
  }
}];

const response = $input.first().json.output ?? $input.first().json.text ?? "";

const cleaned = response
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

const config = $('Config').first().json;

try {
  const draft = JSON.parse(cleaned);
  return [{
    json: {
      ...draft,
      // Carry Slack context forward for the preview + button payload
      slack_channel_id:  config.SLACK_CHANNEL_ID,
      slack_user_id:     config.SLACK_USER_ID,
      slack_response_url: config.SLACK_RESPONSE_URL,
      jira_project_key:  config.JIRA_PROJECT_KEY
    }
  }];
} catch (error) {
  return [{
    json: {
      error: true,
      actionable: false,
      title: "",
      description: `Draft parsing failed: ${error.message}`,
      slack_response_url: config.SLACK_RESPONSE_URL
    }
  }];
}

