// Slack sends the interaction as a URL-encoded 'payload' field
// whose value is a JSON string → parse it
const raw = $input.first().json.body?.payload ?? $input.first().json.payload;

let payload;
try {
  payload = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (error) {
  return [{
    json: {
      error: true,
      error_reason: `Failed to parse Slack payload: ${error.message}`
    }
  }];
}

const action = payload.actions?.[0] ?? {};
const actionId = action.action_id ?? "";
const responseUrl = payload.response_url ?? "";
const clickedBy = payload.user?.id ?? "";

// If "Create" was clicked, decode the ticket JSON stored in the button value
let ticket = null;
if (actionId === "create_ticket") {
  try {
    ticket = JSON.parse(action.value);
  } catch (error) {
    return [{
      json: {
        error: true,
        action_id: actionId,
        response_url: responseUrl,
        error_reason: `Failed to parse ticket from button: ${error.message}`
      }
    }];
  }
}

return [{
  json: {
    error: false,
    action_id: actionId,          // "create_ticket" | "cancel_ticket"
    response_url: responseUrl,
    clicked_by: clickedBy,
    ticket: ticket                // full ticket object, or null if cancelled
  }
}];

